def run(context):
    from datetime import datetime, timedelta
    freshness_threshold = timedelta(days=1)
    report = []
    for date in context['dates_to_check']:
        latest_date = datetime.strptime(date, '%Y-%m-%d')
        if datetime.now() - latest_date > freshness_threshold:
            report.append({'date': date, 'status': 'stale'})
        else:
            report.append({'date': date, 'status': 'fresh'})
    return {'freshness_report': report}
